-- Icaro Ops Asia airport import.
-- Generated from tmp/asia_airports_review.csv.
--
-- Transactional import:
--   - START TRANSACTION is used before any persistent data changes.
--   - Only TEMPORARY tables are created.
--   - Preflight guards intentionally fail before COMMIT if required countries/prefixes are missing.
--   - If the script fails before COMMIT, rerun after fixing data/mapping; persistent DB data remains unchanged.
--
-- Expected base count before this import, if Africa + Antarctica are complete: 1548.
-- Generated unique import rows: 2112.
--
-- Run:
--   sudo mysql icaro_ops < db/mysql/057_import_asia_airports_transactional.sql

USE icaro_ops;

START TRANSACTION;

CREATE TEMPORARY TABLE tmp_asia_airports_import (
  country_name VARCHAR(120) NOT NULL,
  icao_prefix VARCHAR(8) NOT NULL,
  icao_code CHAR(4) NOT NULL,
  iata_code CHAR(3) NULL,
  name VARCHAR(180) NOT NULL,
  city VARCHAR(120) NULL,
  location_name VARCHAR(160) NULL,
  subdivision_name VARCHAR(120) NULL,
  latitude DECIMAL(10,7) NULL,
  longitude DECIMAL(10,7) NULL,
  elevation_ft INT NULL,
  airport_type VARCHAR(40) NOT NULL,
  service_category VARCHAR(40) NOT NULL,
  is_civilian BOOLEAN NOT NULL DEFAULT TRUE,
  is_commercial BOOLEAN NOT NULL DEFAULT TRUE,
  is_military BOOLEAN NOT NULL DEFAULT FALSE,
  is_closed BOOLEAN NOT NULL DEFAULT FALSE,
  operator_country_name VARCHAR(120) NULL,
  data_source_name VARCHAR(120) NULL,
  data_source_url VARCHAR(255) NULL,
  data_quality VARCHAR(40) NOT NULL,
  runway_note TEXT NULL,
  source_row_note TEXT NULL,

  PRIMARY KEY (icao_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

